void fn0() {

  List<List<int>> graph = [
    [0, 1, 1], 
    [1, 0, 1], 
    [1, 1, 0], 
  ];
  int n = graph.length;

  List<bool> visited = List.filled(n, false);
  List<int> stack = [];
  List<int> topologicalSort = [];

  void dfs(int u) {
    visited[u] = true;
    for (int v = 0; v < n; v++) {
      if (!visited[v] && graph[u][v] == 1) {
        dfs(v);
      }
    }
    stack.add(u);
  }

  for (int i = 0; i < n; i++) {
    if (!visited[i]) {
      dfs(i);
    }
  }

  List<int> result = [];
  while (stack.isNotEmpty) {
    int u = stack.removeLast();
    result.add(u);
  }

  if (result.length != n) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${result.join(' -> ')}');
  }
}

