  List<List<int>> graph = [
    [1],
    [2, 3],
    [0, 3],
    [0, 1, 4],
    [2, 4],
  ];

  int n = graph.length;
  List<bool> visited = List.filled(n, false);
  List<int> disc = List.filled(n, 0);
  List<int> low = List.filled(n, 0);
  List<int> stack = [];

  List<int> topologicalSort(List<int> v, int start, List<int> result) {
    visited[start] = true;
    for (int neighbor in v[start]) {
      if (!visited[neighbor]) {
        if (neighbor == start) {
          return [];
        }
        List<int> sortedNeighbors = topologicalSort(v, neighbor, result);
        if (sortedNeighbors.isEmpty) {
          return [];
        }
        result.addAll(sortedNeighbors);
      }
    }
    return result;
  }

  for (int i = 0; i < n; i++) {
    if (!visited[i]) {
      List<int> sorted = topologicalSort(graph, i, []);
      if (sorted.isEmpty) {
        break;
      }
      for (int reversed in sorted.reversed) {
        stack.add(reversed);
      }
    }
  }

  List<int> topologicalSortResult = [];
  while (stack.isNotEmpty) {
    topologicalSortResult.add(stack.removeLast());
  }

  print('Topological Sort: ${topologicalSortResult.join(' -> ')}');
}

