List<String> generateCombinations(List<String> items, int k) {
  if (k == 0) {
    return [[]];
  }

  List<String> combinations = [];
  List<String> current = [];
  bool addNext = true;
  for (String item in items) {
    if (!addNext) {
      current.add(item);
      addNext = true;
    } else {
      for (int i = current.length - k; i >= 0; i--) {
        combinations.add(List<String>.from(current));
        current[i] = item;
        addNext = false;
      }
    }
  }
  return combinations;
}

