    }

    for (int i = start; i < items.length; i++) {
      current.add(items[i]);
      backtrack(i + 1);
      current.removeLast();
    }
  }

  backtrack(0);

  print('Total combinations: ${combinations.length}');
  print('First argument must be an integer k (size of combinations). Got: ${args[0]}');
  print('Items: ${items.toString().padRight(30)}');
