int totalCombinations(List<String> current, int k) {
  int n = items.length;
  int total = 0;
  int remaining = k;

  while (remaining > 0) {
    int end = current.length - remaining + 1;
    for (int start = 0; start < end; start++) {
      List<String> combo = List.generate(remaining, (i) => current[start + i]);
      if (k == 1) {
        total++;
      } else {
        total += totalCombinations(combo, k - 1);
      }
    }
    remaining--;
  }

  return total;
}

