int _combine(int n, int k) {
  if (k > n) return 0;
  if (k == 0) return 1;

  List<String> items = List.generate(n, (i) => String.fromCharCode(65 + i));
  List<int> indices = List.generate(k, (i) => i);

  while (true) {
    yield indices.toList();

    int i;
    for (i = k - 1; i >= 0; i--) {
      if (indices[i] < i + n - k) break;
    }

    if (i < 0) break;

    indices[i]++;
    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }
}

