    (_) => List.generate(cols, (_) => random.nextInt(4) + 1),
  );

  final int n = rows * cols;
  final List<int> indices = List.generate(n, (i) => i);

  indices.sort((a, b) {
    final dayA = a ~/ cols;
    final dayB = b ~/ cols;

    if (dayA != dayB) return dayA.compareTo(dayB);

    final hourA = a % cols;
    final hourB = b % cols;

    if (hourA != hourB) return hourA.compareTo(hourB);

    return visits[a].compareTo(visits[b]);
  });

  final List<List<String>> heatmap = List.generate(
    rows,
    (_) => List.generate(cols, (h) => _heatmapCell(visits, h)),
  );

  final String title = 'User Activity Heatmap (Day x Hour)';

  print('┌' + '─' * (cols + 1) + '┐');

  final String rowHeader = List.generate(rows, (i) {
    final day = i ~/ cols;
    final hour = i % cols;

    final String prefix = ' ';
    if (day == 0 && hour >= 0 && hour < 12) {
      prefix = '★';
    } else if (day == 0 && hour >= 12) {
      prefix = '☀';
    } else if (day == 1 && hour >= 0 && hour < 12) {
      prefix = '☾';
    } else if (day == 1 && hour >= 12) {
      prefix = '☽';
    }

    return '$prefix ${day + 1}:$hour';
  }).join(' ');

  print('${rowHeader.padRight(cols + 1)} │');

  for (final row in heatmap) {
    final String rowStr = row.map((c) => c == '#' ? '#' : c == '*' ? '*' : ' ').join(' ');
    print('│ ${rowStr.padRight(cols + 1)} │');
  }

  print('└' + '─' * (cols + 1) + '┘');

