  print('  \".\" = low');
  print('  \"#\" = high');
  print('  \"*\" = medium');
  print('  \" \" = no activity');
}

String _heatmapCell(List<List<int>> visits, int cell) {
  final int i = visits[cell];
  final double day = (cell ~/ visits.length) * 7;
  final double hour = (cell % visits.length) * 60;

  if (i == 0) return ' ';
  if (i == 1) return '.';
  if (i == 2) return '*';
  if (i == 3) return '#';

  final double density = i / 3.0;
  double dayPct = density * day;

  if (dayPct > 0.66) {
    dayPct = 0.66;
  }

  if (hourPct >= 0.33) {
    hourPct = 0.33;
  }

  if (dayPct > hourPct) {
    return '#';
  } else if (hourPct - dayPct > 0.16) {
    return '*';
  } else {
    return '.';
  }
}

