    'Diamonds': 0,
    'Spades': 0,
    'Clubs': 0,
  };
  const suitOrder = {'Hearts', 'Diamonds', 'Spades', 'Clubs'};
  const suitMap = {'Hearts': 0, 'Diamonds': 1, 'Spades': 2, 'Clubs': 3};
  const suitSymbols = {'Hearts': '❤️', 'Diamonds': '♦', 'Spades': '♠', 'Clubs': '♣'};
  for (int i = 0; i < p0.length; i++) {
    String ch = p0[i];
