  void solve(int depth) {
    if (depth == maxDepth) {

      bool isSafe = true;
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
          if (board[i][j] == 1) {
            isSafe = false;
            break;
          }
        }
        if (!isSafe) break;
      }

      if (isSafe) {
        for (int i = 0; i < n; i++) {
          String row = '';
          for (int j = 0; j < n; j++) {
            if (board[i][j] == 1) row += 'Q ';
          }
          print('Solution ${solutionCount + 1}: $row');
        }
        solutionCount++;
        return;
      }
    }

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (board[i][j] == 0) {
          board[i][j] = 1;
          if (isSafe(i, j)) {
            solve(depth + 1);
          }
          board[i][j] = 0;
        }
      }
    }
  }

  void printBoard(List<List<int>> b) {
    for (int i = 0; i < n; i++) {
      String row = '';
      for (int j = 0; j < n; j++) {
