    for (int i = 0; i < r; i++) {
      if (board[i][c] == 1) return false;
    }

    int i = r - 1;
    int j = c - 1;
    while (i >= 0 && j >= 0) {
      if (board[i][j] == 1) return false;
      i--;
      j--;
    }

    i = r - 1;
    j = c + 1;
    while (i >= 0 && j < n) {
      if (board[i][j] == 1) return false;
      i--;
      j++;
    }

    return true;
  }

  solve(0);
  print('Total solutions: $solutionCount');
}

