  if (durations.isEmpty) return {'pairCount': 0, 'mashupDuration': 0};
  int left = 0, right = durations.length - 1;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    if (durations[mid] > maxDuration) {
      right = mid;
