  }
  int end = left;
  int pairCount = 0;
  int currentDuration = 0;
  for (int i = left; i < durations.length; i++) {
    currentDuration += durations[i];
    if (i - end + 1 >= 2) {
      pairCount++;
    }
    if (currentDuration > maxDuration) {
      break;
    }
  }
  return {'pairCount': pairCount, 'mashupDuration': currentDuration};
}

