class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.unit() : this(1.0, 0.0, 0.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.fromList(List<double> data) : this(data[0], data[1], data[2], data[3]);

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  double conjugate() => Quaternion(x, y, -z, w);

  Quaternion inverse() => Quaternion(x, y, z, 1.0 / w);

  Quaternion rotate(double theta, Quaternion axis) {
    double sinTheta = sin(theta);
    double cosTheta = cos(theta);

    double xx = x * x;
    double yy = y * y;
    double zz = z * z;
    double wx = x * w;
    double wy = y * w;
    double wz = z * w;

    return Quaternion(
        (xx * cosTheta + sinTheta * zz) * cosTheta + 2 * wx * sinTheta,
        (yy * cosTheta + sinTheta * wy) * cosTheta + 2 * wy * sinTheta,
        (zz * cosTheta + sinTheta * wx) * cosTheta + 2 * wz * sinTheta,
        sinTheta * (wx * wy - xx * wz));
  }

  double dot(Quaternion other) => x * other.x + y * other.y + z * other.z + w * other.w;

  @override
  bool operator ==(Object other) {
    if (other is Quaternion) {
      return x == other.x && y == other.y && z == other.z && w == other.w;
    }
    return false;
  }

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  @override
  String toString() {
    String normStr = norm().toString();
    String concStr = conjugate().toString();
    String normConStr = '${normStr}:${concStr}';
    return normConStr;
  }
}

