  const Quaternion.left => const Quaternion(-1, 0, 0, 0);

  const Quaternion.identity => const Quaternion(1, 0, 0, 0);

  const Quaternion.random => const Quaternion(
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
    (4 * (Math.random() * 2 - 1)).toDouble(),
  );

