      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(covariant Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(covariant Quaternion other) {
    final x = other.x * w - other.w * x;
    final y = other.x * z + other.z * x;
    final z = other.y * w - other.w * y;
    final w = other.y * z + other.z * y;
    return Quaternion(x, y, z, w);
  }

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator ^(int rounds) {
    var q = this;
    for (var i = 0; i < rounds; i++) {
      q = q * q * q * q;
    }
    return q;
  }

