      Quaternion(list[0] * list[1], list[2] * list[3], list[4] * list[5], list[6] * list[7]);

  const Quaternion operator ^(covariant List<int> list) =>
      Quaternion(list[0] ^ list[1] ^ list[2] ^ list[3]);

