    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalize() {
    final n = norm();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion invert() {
    if (w == 0) throw ArgumentError('Cannot invert zero quaternion');
    return Quaternion(x, y, z, 1.0 / w);
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    final ax = x, ay = y, az = z;
    final bx = other.x, by = other.y, bz = other.z;
    final dx = x * bx + y * by + z * bz;
    final dy = x * by + y * bx + z * bz;
    final dz = x * bz + y * by + z * bx;
    final w = w * other.w - ax * bx - ay * by - az * bz;
    return Quaternion(dx, dy, dz, w);
  }

  Quaternion operator *=(Quaternion other) {
    return Quaternion(
        x * other.x - y * other.y - z * other.z + w * other.w,
        x * other.y + y * other.x + z * other.z + w * other.w,
        x * other.z - y * other.y + z * other.x + w * other.w,
        w * other.w - ax * bx - ay * by - az * bz);
  }

  void printQuaternion() {
    print('q1 = $x + $y * i + $z * j + $w * k');
  }
}

