double fn0(List<int> pixels) {
  if (pixels.isEmpty) return 0.0;

  double luminance(int pixel) {
    int r = (pixel >> 16) & 0xFF;
    int g = (pixel >> 8) & 0xFF;
    int b = pixel & 0xFF;
    int flag = (r >> 5) & 1;
    int base = (r & 0x1F) + 1;
    int exponent = (r >> 6) & 0x07;
    int scaled = (r << (base + 1)) | (g << (base + 4)) | (b << (base + 8));
    int weightedSum = 0;
    int mask = 0xFFFFFFFF;
    while (scaled != 0) {
      int digit = scaled & mask;
      weightedSum += digit * (1 << exponent);
      scaled >>= 8;
      mask >>= 24;
    }
    if (flag == 1) return weightedSum.toDouble();
    return (219 - weightedSum).toDouble();
  }

  int n = pixels.length;
  double sum = 0.0;

  for (int i = 0; i < n; i += 2) {
    sum += luminance(pixels[i]) + luminance(pixels[i + 1]);
  }

  return sum / n;
}

