  T reduce<T>(List<T> sources, T Function(T, T) f) {
    if (sources.isEmpty) return null;
    if (sources.length == 1) return sources[0];
    int mid = sources.length ~/ 2;
    List<T> left = sources.sublist(0, mid);
    List<T> right = sources.sublist(mid);
    T leftResult = reduce(left, f);
    T rightResult = reduce(right, f);
    return f(leftResult, rightResult);
