Map<String, int> fn0(List<int> weights, int capacity) {
  int n = weights.length;
  List<int> dp = List.filled(n + 1, 0);

  for (int i = 1; i <= n; i++) {
    dp[i] = dp[i - 1] + weights[i - 1];
    if (i >= 2) {
      dp[i] = dp[i] < dp[i - 2] + weights[i - 2] ? dp[i] : dp[i - 2] + weights[i - 2];
    }
  }

  Map<String, int> result = {};
  int currentSum = 0;
  int maxLen = 0;
  int bestStart = 0;

  for (int i = 0; i <= n; i++) {
    if (dp[i] <= capacity) {
      int len = i - bestStart + 1;
      result['$len-$currentSum'] = len;
      currentSum += dp[i];
      if (len > maxLen) {
        maxLen = len;
        bestStart = i;
      }
    } else {
      break;
    }
  }

  return result;
}

