Map<String, int> fn0(List<int> schedule, int delayMinutes) {
  int n = schedule.length;
  if (n == 0) return {};
  List<int> dp = List.filled(n + 1, 1000000);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      int gap = schedule[i - 1] - schedule[j];
      if (gap <= 0) continue;
      if (gap > delayMinutes) gap = delayMinutes;
      int cost = dp[j] + gap;
      if (cost < dp[i]) dp[i] = cost;
    }
  }
  Map<String, int> result = {};
  int minCost = dp[n] == 1000000 ? -1 : dp[n];
  if (minCost >= 0) {
    result["0-$minCost"] = 1;
  }
  for (int i = n - 1; i >= 0; i--) {
    int cost = dp[i];
    if (cost == 1000000) continue;
    String key = "$i-$cost";
    result[key] = (result[key] ?? 0) + 1;
  }
  return result;
}

