      dp[i] = dp[i - 1] + 1;
    } else {
      dp[i] = 0;
    }

    if (dp[i] > counts['high']!) {
      counts['high'] = dp[i];
    } else if (dp[i] > counts['mid']!) {
      counts['mid'] = dp[i];
    } else {
      counts['low'] = dp[i];
    }
  }

  return counts;
}

