List<String> fn0(List<String> logLines) {
  List<String> brackets = [];
  List<String> results = [];
  for (String line in logLines) {
    if (line == 'OPEN') {
      brackets.add('');
    } else if (line == 'CLOSE') {
      if (brackets.isEmpty) {
        results.add('D:0,result=0');
        continue;
      }
      String inside = brackets.removeLast();
      List<String> parts = inside.split(';');
      int depth = 0;
      bool corrupted = false;
      for (String part in parts) {
        if (part.isEmpty) {
          corrupted = true;
          break;
        }
        List<String> pair = part.split(',');
        if (pair.length != 2) {
          corrupted = true;
          break;
        }
        String open = pair[0];
        String close = pair[1];
        if (open != '<' || close != '>') {
          corrupted = true;
          break;
        }
        if (open != '<') {
          depth++;
        } else if (close != '>') {
          corrupted = true;
          break;
        }
        if (open == '<' && close == '>') {
          depth--;
        }
        if (corrupted) {
          break;
        }
      }
      if (corrupted) {
        results.add('D:$depth,result=0');
      } else {
        int checksum = 0;
        for (String bracket in parts) {
          if (bracket.isNotEmpty) {
            checksum += bracket.length;
          }
        }
        results.add('D:$depth,result=$checksum');
      }
    } else if (line.startsWith('C:')) {
      String countStr = line.substring(2);
      int? count = int.tryParse(countStr);
      if (count == null || count < 0) {
        results.add('D:0,result=0');
        continue;
      }
      for (int i = 0; i < count; i++) {
        brackets.add('');
      }
    } else if (line.startsWith('FINAL:')) {
      String marker = line.substring(7);
      if (!brackets.contains(marker)) {
        results.add('D:0,result=0');
        continue;
      }
      int net = 0;
      for (String bracket in brackets) {
        net += bracket.length;
      }
      results.add('CLOSE:net=$net');
    }
  }
  return results;
}

