        } else if (pw.codeUnitAt(j) == pw.codeUnitAt(k)) {
          if (dp[i][k] > 0 && pw.codeUnitAt(j) > pw.codeUnitAt(i)) {
            dp[i][j] = dp[i][j] + dp[i][k];
            newStrong++;
          }
        }
      }
      if (newStrong >= minStrong) {
        strong++;
        positions.add(j);
      }
    }
    positions.sort();
    if (strong >= minStrong) result.add(pw + " " + strong.toString() + "(" + positions.join(", ") + ")");
  }
  return result;
}

