  if (items.isEmpty) return result;

  int n = items.length;
  List<List<int>> dp = List.generate(n, (_) => List.filled(n, 0));

  for (int i = 0; i < n; i++) {
    for (int j = 0; j <= i; j++) {
      int sum = 0;
      bool valid = true;
      for (int k = j; k < i; k++) {
        sum += items[k];
        if (sum > limit) {
          valid = false;
          break;
        }
      }
      if (valid) {
        dp[i][j] = 1;
      }
    }
  }

  int count = 0;
  for (int j = 0; j < n; j++) {
    if (dp[n - 1][j] == 1) count++;
  }

  return count;
}

