  void heapify(List<int> arr, int size, int root) {
    int largest = root;     
    int left  = 2 * root + 1;
    int right = 2 * root + 2;

    if (left < size && arr[left] > arr[largest]) largest = left;
    if (right < size && arr[right] > arr[largest]) largest = right;

    if (largest != root) {

      int temp = arr[root];
      arr[root] = arr[largest];
      arr[largest] = temp;

      heapify(arr, size, largest);
    }
  }

  void heapSort(List<int> arr) {
    int n = arr.length;

    for (int i = n ~/ 2 - 1; i >= 0; i--) {
      heapify(arr, n, i);
    }

    for (int i = n - 1; i > 0; i--) {

      int temp = arr[0];
      arr[0] = arr[i];
      arr[i] = temp;

      heapify(arr, i, 0);
    }
  }

  heapSort(arr);

  print('Sorted array: $arr');
}

