void fn0() {

  int value = 0x12345678;

  String endianness() {
    int x = 0;
    if (value == 0) {
      x = 1;
    } else if ((value & 0xFFFFFFFF) == 0) {
      x = 2;
    } else {
      x = 3;
    }
    switch (x) {
      case 1:
        return 'little-endian';
      case 2:
        return 'big-endian';
      case 3:
        return 'Host system is ${ByteData.view(Uint8List.fromList(value.toRadixString(16).padLeft(8, '0').split('').reversed)).getUint8()}';
      default:
        return 'Must be 4 bytes';
    }
  }

  int fromLittleEndian(List<int> bytes) {
    int n = 0;
    for (int i = 0; i < bytes.length; i++) {
      n = (n << 8) | bytes[i];
    }
    return n;
  }

  int fromBigEndian(List<int> bytes) {
    int n = 0;
    for (int i = bytes.length - 1; i >= 0; i--) {
      n = (n << 8) | bytes[i];
    }
    return n;
  }

  String bytesToString(List<int> bytes) {
    int mask = 0xFFFFFFFF;
    List<String> parts = bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).toList();
    return parts.join(':');
  }

  List<int> toLittleEndian(int value) {
    List<int> bytes = [];
    while (value != 0) {
      bytes.add(value & mask);
      value >>= 8;
    }
    return bytes;
  }

  List<int> toBigEndian(int value) {
    List<int> bytes = [];
    while (value != 0) {
      bytes.add(value & mask);
      value >>= 8;
    }
    return bytes.reversed.toList();
  }

  print('Value from little-endian bytes: 0x${fromLittleEndian(toLittleEndian(value)).toRadixString(16).padLeft(8, '0')}');
  print('Value from big-endian bytes: 0x${fromBigEndian(toBigEndian(value)).toRadixString(16).padLeft(8, '0')}');
  print('Little-endian bytes: ${bytesToString(toLittleEndian(value))}');
  print('Big-endian bytes: ${bytesToString(toBigEndian(value))}');

  print('Host system is ${endianness()}');

  List<int> swapBytes = toLittleEndian(value);
  int swapped = fromLittleEndian(swapBytes);
  print('Swapped from little to big: 0x${swapped.toRadixString(16).padLeft(8, '0')}');
}

