    for (var action in actions) {
      if (resourcesForRole.containsKey(action)) {
        final List<bool> permissions = resourcesForRole[action]!;
        permissions[0] = false; 
        resourceRoles[action] = permissions;
      }
    }
  }

  void createRole(String name) {
    final Map<String, List<bool>> newRole = <String, bool>{};
    for (var resource in resources.keys) {
      newRole[resource] = false;
    }
    roles[name] = newRole;
    print('New role for $name created.');
  }

  void elevate(String user, String role) {
    final List<bool> newPermissions = List.from(userRoles[user]!);
    for (var i = 0; i < 4; i++) {
      if (!roleAdminRoles[i]) newPermissions[i] = true;
    }
    userRoles[user] = newPermissions;
    print('Elevating $user to $role role...');
  }

  void denyAll(String role) {
    final Map<String, List<bool>> resources = roles[role]!;
    for (var resource in resources.keys) {
      final List<bool> permissions = resources[resource]!;
      for (var i = 0; i < 4; i++) {
        permissions[i] = false;
      }
      resourceRoles[resource] = permissions;
    }
    print('All permissions for $role role removed.');
  }

  void listRoles() {
    print('Total Roles: ${roles.length}');
    for (var role in roles.keys) {
      print('$role: ${getRoleName(roles[role]!)}');
    }
  }

  void listResources() {
    print('Total Resources: ${resources.length}');
    for (var resource in resources.keys) {
      print('$resource: ${getRoleName(resourceRoles[resource]!)}');
    }
  }

  void listUsers() {
    print('Total Users: ${userRoles.length}');
    for (var user in userRoles.keys) {
      print('$user: ${getRoleName(userRoles[user]!)}');
    }
  }

  void printUserPermissions(String user) {
    print('User: $user');
    print('Permissions:');
    for (var resource in resources.keys) {
      final List<bool> permissions = getUserPermissions(user)[resource]!;
      bool hasAccess = permissions[0];
      for (var i = 1; i < 4; i++) {
        if (!permissions[i]) {
          hasAccess = false;
          break;
        }
      }
      if (hasAccess) {
        print('  $resource: ${permissions.join(", ")}');
      } else {
        print('  $resource: DENIED');
      }
    }
  }

  void audit(String action, String user, String resource) {
    final String timestamp = DateTime.now().toString();
    print('[$timestamp] $action: ${user} attempted to $action on $resource');
  }

  void logAccess(String user, String resource, String action) {
    if (action == 'read') {
      print('User $user read $resource.');
    } else if (action == 'write') {
      print('User $user wrote to $resource.');
    } else if (action == 'delete') {
      print('User $user deleted $resource.');
    } else {
      print('  $user attempted to $action on $resource');
    }
  }

  print('=== Role-Based Access Control System ===\n');

  grantAccess('admin', 'admin', ['CREATE', 'READ', 'WRITE', 'DELETE', 'admin']);
  grantAccess('editor', 'editor', ['READ', 'WRITE', 'DELETE', 'edit', 'manage']);
  grantAccess('moderator', 'moderator', ['READ', 'WRITE', 'DELETE', 'content_moderation']);
  grantAccess('viewer', 'viewer', ['READ', 'VIEW', 'public_viewing']);

  denyAccess('admin', 'admin', ['CREATE', 'READ', 'WRITE', 'DELETE', 'admin']);
  denyAll('moderator');

  createRole('super_admin');
  elevate('alice', 'super_admin');
  print('Current role for alice: ${getRoleName(userRoles['alice']!)}');

  listRoles();
  listResources();
  listUsers();

  audit('CREATE', 'bob', 'document2');
  logAccess('bob', 'document2', 'write');

  print('\n--- User Permissions Overview ---\n');
  for (var user in userRoles.keys) {
    printUserPermissions(user);
  }

  print('\n--- Resource Access Matrix ---\n');
  for (var resource in resources.keys) {
    print('$resource: ${getRoleName(resourceRoles[resource]!)}');
  }

  print('\n--- Access Control Tests ---\n');
  for (var user in userRoles.keys) {
    for (var resource in resources.keys) {
      if (!resourceRoles[resource]!.contains(0)) continue; 
      bool allowed = false;
      for (var action in actions) {
        if (getUserPermissions(user)[resource]![action]!) {
          allowed = true;
          break;
        }
      }
      if (allowed) {
        print('User $user can $action on $resource.');
      } else {
        print('User $user cannot $action on $resource.');
      }
    }
  }

  print('\n=== System Summary ===\n');
  print('Total Permissions: ${userRoles.length + resourceRoles.length}');
}

