  };

  double minSupport = 0.5; 
  double minConfidence = 0.7;   

  int k = 2; 

  Map<String, int> itemCount = {};
  Map<List<String>, int> frequentItemsets = <List<String>, int>{};

  for (var entry in transactionSet.entries) {
    for (var item in entry.value) {
      itemCount[item] = (itemCount[item] ?? 0) + 1;
    }
  }

  List<String> allItems = [];
  for (var entry in transactionSet.entries) {
    allItems.addAll(entry.value);
  }

  int minSupportCount = (minSupport * allItems.length).round();

  Set<List<String>> frequentItemsets = {};

  while (true) {
    Map<List<String>, int> currentItemsetSupport = <List<String>, int>{};
    for (var item in allItems) {
      currentItemsetSupport[item] = 0;
    }

    for (var entry in transactionSet.entries) {
      var itemset = entry.key.split(' ');
      if (itemset.length <= k) {
        for (var item in entry.value) {
          currentItemsetSupport[item] = (currentItemsetSupport[item] ?? 0) + 1;
        }
      }
    }

    List<String> currentFrequentItemsets = <String>[];
    for (var item in allItems) {
      if (currentItemsetSupport[item]! >= minSupportCount) {
        currentFrequentItemsets.add(item);
      }
    }

    if (currentFrequentItemsets.isEmpty) {
      break;
    }

    frequentItemsets.addAll(currentFrequentItemsets);

    if (k < 6) {
      k++;
    } else {
      break;
    }
  }

  print('Frequent Itemsets:');
  print(frequentItemsets.toList());

  Map<List<String>, List<String>> associationRules = <List<String>, List<String>>{};

  for (var itemset in frequentItemsets) {
    if (itemset.length < 2) {
      continue;
    }

    for (var index = 0; index < itemset.length - 1; index++) {
      List<String> left = itemset.sublist(0, index + 1);
      List<String> right = itemset.sublist(index + 1);

      double leftSupport = itemCount[left.join(' ')]! / allItems.length;
      double rightSupport = itemCount[right.join(' ')]! / allItems.length;
      double confidence = leftSupport / rightSupport;

      if (confidence >= minConfidence) {
        if (!associationRules.containsKey(left)) {
          associationRules[left] = <String>[];
        }
        associationRules[left]!.add(right);
      }
    }
  }

  print('\nAssociation Rules:');
  for (var itemset in associationRules.entries) {
    print('${itemset.key} -> ${itemset.value.join(' ')} (support: ${itemset.value.length}, confidence: ${itemset.value.length / itemset.key.length});');
