class Rectangle {
  final double width;
  final double height;
  final double centerX;
  final double centerY;

  const Rectangle(this.width, this.height, [this.centerX = 0.0, this.centerY = 0.0]);

  const Rectangle.unit() : this(1.0, 1.0);

  const Rectangle.origin() : this(0.0, 0.0);

  const Rectangle.square() : this(200.0);

  const Rectangle.circle() : this(100.0, 100.0);

  const Rectangle.bounded() : this(200.0, 400.0);

  Rectangle.origin() => this(0.0, 0.0);

  bool contains(Point p) {
    return p.x >= centerX - width &&
        p.x <= centerX + width &&
        p.y >= centerY - height &&
        p.y <= centerY + height;
  }

  bool contains(Rectangle other) {
    return contains(other.center) &&
        contains(other.origin) &&
        contains(other.square) &&
        contains(other.circle);
  }

  Rectangle union(Rectangle other) {
    double left = min(centerX - width, other.centerX - other.width);
    double right = max(centerX + width, other.centerX + other.width);
    double bottom = min(centerY - height, other.centerY - other.height);
    double top = max(centerY + height, other.centerY + other.height);
    return Rectangle(right - left, top - bottom, centerX - (right - left) / 2, centerY - (top - bottom) / 2);
  }

  @override
  String toString() => 'Rectangle(center: (${centerX}, ${centerY}), halfWidth: ${width / 2}, halfHeight: ${height / 2})';
}

