class Point {
  double x1, y1; 
  double r;  
  List<double> range; 

  Point(this.x1, this.y1, [this.r = 0.0, this.range = [0, 0, 0, 0, 0]]);

  Point.origin() : this(0, 0, 50, [1, 1, 1, 1, 1]);

  Point.unit() : this(0, 0, 50, [1, 1, 1, 0, 0]);

  Point.random() : this(
    rand.nextInt(100) - 50, 
    rand.nextInt(100) - 50, 
    rand.nextDouble() * 50, 
    [
      rand.nextInt(2) == 0 ? 1 : 0,
      rand.nextInt(2) == 0 ? 1 : 0,
      rand.nextInt(2) == 0 ? 1 : 0,
      rand.nextInt(2) == 0 ? 1 : 0,
      rand.nextInt(2) == 0 ? 1 : 0,
    ],
  );

  bool contains(double px, double py) {
    if (r == 0) return true;
    return (px - x1).abs() + (py - y1).abs() <= r;
  }

  bool overlaps(Rectangle other) {
    return !(
        (x1 > other.x1 + other.width) ||
        (x1 + width < other.x1) ||
        (y1 > other.y1 + other.height) ||
        (y1 + height < other.y1)
    );
  }
}

class Rectangle {
  double x1, y1, x2, y2; 
  double width, height; 

  Rectangle(this.x1, this.y1, this.x2, this.y2)
      : width = x2 - x1,
        height = y2 - y1;

  bool contains(double px, double py) {
    return x1 < px && px < x2 + width && y1 < py && py < y2 + height;
  }

  bool overlaps(Rectangle other) {
    if ((x1 < other.x1 + other.width) != (x2 > other.x1)) return false;
    if ((y1 < other.y1 + other.height) != (y2 > other.y1)) return false;
    return true;
  }

  Rectangle union(Rectangle other) {
    double nx1 = x1 < other.x1 ? x1 : other.x1;
    double ny1 = y1 < other.y1 ? y1 : other.y1;
    double nx2 = x2 > other.x2 + other.width ? x2 : other.x2 + other.width;
    double ny2 = y2 > other.y2 + other.height ? y2 : other.y2 + other.height;
    return Rectangle(nx1, ny1, nx2, ny2);
  }

  Rectangle intersection(Rectangle other) {
    if (!overlaps(other)) return Rectangle.unit();
    double minX = x1 < other.x1 ? x1 : other.x1;
    double minY = y1 < other.y1 ? y1 : other.y1;
    double maxX = x2 > other.x2 + other.width ? x2 : other.x2;
    double maxY = y2 > other.y2 + other.height ? y2 : other.y2;
    return Rectangle(minX, minY, maxX, maxY);
  }

  void translate(double dx, double dy) {
    x1 += dx;
    x2 += dx;
    y1 += dy;
    y2 += dy;
  }
}

