/// Abstract class acting as an interface for shapes.
abstract class Shape {
  factory Shape(String type, List<double> points) {
    switch (type) {
      case 'rectangle':
        return Rectangle(points);
      case 'circle':
        return Circle(points);
      case 'ellipse':
        return Ellipse(points);
      default:
        throw ArgumentError('Unsupported shape type: $type');
    }
  }

  List<double> get points;
  double get centerX;
  double get centerY;
  double get width;
  double get height;
}

/// Class implementing the Shape interface.
class Rectangle implements Shape {
  final List<double> points;
  final double centerX;
  final double centerY;
  final double width;
  final double height;

  Rectangle(this.points)
      : centerX = points[0] + points[2] / 2,
        centerY = points[1] + points[3] / 2,
        width = points[2] - points[0],
        height = points[3] - points[1];

  @override
  List<double> get points => [centerX, centerY, centerX + width, centerY + height];

  @override
  double get centerX => centerX;

  @override
  double get centerY => centerY;

  @override
  double get width => width;

  @override
  double get height => height;

  @override
  String toString() => 'Rectangle(center: ($centerX, $centerY), width: $width, height: $height)';
}

/// Class implementing the Shape interface.
class Circle implements Shape {
  final List<double> points;
  final double centerX;
  final double centerY;
  final double radius;

  Circle(this.points)
      : centerX = points[0],
        centerY = points[1],
        radius = points[2];

  @override
  List<double> get points => [centerX, centerY, centerX + radius, centerY + radius];

  @override
  double get centerX => centerX;

  @override
  double get centerY => centerY;

  @override
  double get radius => radius;

  @override
  String toString() => 'Circle(center: ($centerX, $centerY), radius: $radius)';
}

/// Class implementing the Shape interface.
class Ellipse implements Shape {
  final List<double> points;
  final double centerX;
  final double centerY;
  final double halfWidth;
  final double halfHeight;

  Ellipse(this.points)
      : centerX = points[0],
        centerY = points[1],
        halfWidth = points[2],
        halfHeight = points[3];

  @override
  List<double> get points => [centerX, centerY, centerX + halfWidth, centerY + halfHeight];

  @override
  double get centerX => centerX;

  @override
  double get centerY => centerY;

  @override
  double get halfWidth => halfWidth;

  @override
  double get halfHeight => halfHeight;

  @override
  String toString() => 'Ellipse(center: ($centerX, $centerY), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

