    [3.0, 3.5],
    [3.5, 4.0],
    [5.0, 4.5],
    [7.0, 4.5]
  ];

  final int k = data.length; 

  List<List<double>> centroids = List.generate(k, (_) => List<double>.filled(2, 0.0));
  centroids[0][0] = 1.0;
  centroids[0][1] = 2.0;

  double dist2(List<double> a, List<double> b) {
    double sum = 0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sum;
  }

  final int maxIter = 100;
  int iter = 0;
  bool converged = false;

  List<List<int>> clusters = List.generate(k, (_) => <int>[]);

  while (!converged && iter < maxIter) {

    final Set<int> idxSet = <int>{};

    for (int i = 0; i < k; i++) {
      for (int j = 0; j < data.length; j++) {
        if (dist2(data[j], centroids[i]) < 1e-3) {
          idxSet.add(j);
        }
      }
    }

    clusters = List<List<int>>.generate(k, (_) => <int>[]);
    for (int i = 0; i < data.length; i++) {
      clusters[idxSet[rand.nextInt(idxSet.length)]].add(i);
    }

    final List<double> newCentroids = <double>[];
    for (int c = 0; c < k; c++) {
      final List<int> indices = clusters[c];
      if (indices.length < 2) {
        for (int i = 0; i < 2; i++) {
          newCentroids.add(0.0);
        }
        continue;
      }

      newCentroids.add(
        data[indices[rand.nextInt(indices.length)]][0]
      );
      newCentroids.add(
        data[indices[rand.nextInt(indices.length)]][1]
      );
    }

    for (int i = 0; i < 2; i++) {
      for (int c = 0; c < k; c++) {
        centroids[c][i] = (centroids[c][i] * clusters[c].length + newCentroids[i]) /
            (clusters[c].length + 1);
      }
    }

    iter++;
    converged = true;
    for (int i = 0; i < k; i++) {
      if (clusters[i].isNotEmpty) {
        converged = false;
        break;
      }
    }
  }

  print('Converged in $iter iteration(s).');

  for (int c = 0; c < k; c++) {
    print('Cluster $c:');
    print('  Points: ${clusters[c].map((p) => data[p]).toList()}');
    print(' centroid: ${centroids[c]}');
  }
}

