    [3.0, 3.0],
    [3.5, 4.0],
    [4.0, 4.5],
    [5.0, 5.0],
    [7.0, 0.0],
  ];

  final k = 3;

  final int n = points.length;

  List<List<int>> labels = List.generate(n, (_) => List.filled(k, 0));

  List<int> centroids = List.generate(k, (_) => points[random.nextInt(n)]);

  double eps = 0.0;
  int maxIterations = 100;

  for (int iter = 0; iter < maxIterations; iter++) {

    List<int> assignments = List.filled(n, 0);

    for (int i = 0; i < n; i++) {
      double minDist = double.infinity;
      int bestCent = 0;

      for (int c = 0; c < k; c++) {
        double dist = (points[i][0] - centroids[c][0]).abs() +
            (points[i][1] - centroids[c][1]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestCent = c;
        }
      }

      assignments[i] = bestCent;
      labels[i][bestCent]++;
    }

    List<List<double>> newCentroids = List.generate(k, (_) => [0.0, 0.0]);

    for (int c = 0; c < k; c++) {
      for (int i = 0; i < n; i++) {
        if (assignments[i] == c) {
          newCentroids[c][0] += points[i][0];
          newCentroids[c][1] += points[i][1];
        }
      }
    }

    for (int c = 0; c < k; c++) {
      newCentroids[c][0] /= labels[c][0];
      newCentroids[c][1] /= labels[c][0];
    }

    double deltaSum = 0.0;

    for (int c = 0; c < k; c++) {
      for (int i = 0; i < n; i++) {
        if (assignments[i] == c) {
          double dist = (points[i][0] - newCentroids[c][0]).abs() +
              (points[i][1] - newCentroids[c][1]).abs();
          deltaSum += dist;
        }
      }
    }

    if (deltaSum < eps) {
      print('Converged in $iter iteration(s).');
      break;
    }

    centroids = List.from(newCentroids);
  }

  print('Cluster $c: centroid: ${centroids[c][0]}, ${centroids[c][1]}');

  List<List<int>> pointsInCluster = List.generate(k, (_) => []);
  for (int i = 0; i < n; i++) {
    if (labels[i][c] > 0) {
      pointsInCluster[c].add(i);
    }
  }

  print('  Points: $pointsInCluster');
}

