void fn0() {

  final rng = Random(0);

  final data = [
    [2.0, 3.0],
    [2.5, 4.0],
    [4.0, 4.5],
    [5.0, 3.5],
    [0.0, 1.0],
    [1.5, 2.0],
    [7.0, 2.0],
    [1.5, 2.5],
  ];

  const int k = 3; 
  const double eps = 1e-4; 
  const int maxIterations = 100;

  List<List<double>> points = List.from(data);
  List<int> clusters = List.filled(points.length, 0);

  Set<int> visited = {};

  int find(int i) {
    if (clusters[i] == 0) {
      clusters[i] = i;
      return i;
    }
    return clusters[i] = find(clusters[i]);
  }

  void union(int x, int y) {
    var rootX = find(x);
    var rootY = find(y);
    if (rootX != rootY) {
      if (rootX < rootY) {
        clusters[rootX] = rootY;
      } else {
        clusters[rootY] = rootX;
      }
    }
  }

  for (int i = 0; i < points.length; i++) {
    visited.add(i);
  }

  int clusterId = 0;

  for (int i = 0; i < maxIterations; i++) {
    int count = 0;
    List<List<double>> newPoints = List.generate(points.length, (_) => []);

    for (int idx in visited) {
      newPoints[count] = points[idx];
      count++;
    }

    for (int p = 0; p < count; p++) {
      for (int q = p + 1; q < count; q++) {
        double dist = (newPoints[p][0] - newPoints[q][0]).abs() +
            (newPoints[p][1] - newPoints[q][1]).abs();
        if (dist <= eps) {
          union(p, q);
        }
      }
    }

    bool converged = true;

    for (int idx in visited) {
      if (find(idx) != clusters[idx]) {
        converged = false;
      }
    }

    if (converged) {
      break;
    }

    List<List<double>> centers = List.generate(k, (_) => [0.0, 0.0]);
    List<int> clusterSizes = List.filled(k, 0);

    for (int idx in visited) {
      int clusterId = find(idx);
      centers[clusterId][0] += newPoints[idx][0];
      centers[clusterId][1] += newPoints[idx][1];
      clusterSizes[clusterId]++;
    }

    for (int c = 0; c < k; c++) {
      centers[c][0] /= clusterSizes[c];
      centers[c][1] /= clusterSizes[c];
    }

    for (int i = 0; i < points.length; i++) {
      int clusterId = find(i);
      points[i][0] -= centers[clusterId][0];
      points[i][1] -= centers[clusterId][1];
    }
  }

  print('Cluster $clusterId:');
  for (int i = 0; i < points.length; i++) {
    print('  ${points[i][0]}, ${points[i][1]}');
  }
  print(' centroid: ${centers[clusterId][0]}, ${centers[clusterId][1]}');
  print('Converged in $i iteration(s).');
}

