    for (int i = 0; i < p1.length; i++) {
      sum += pow(p1[i] - p2[i], 2);
    }
    return sqrt(sum);
  }

  double centroidDistance(List<List<double>> clusters, int index) {
    double minDist = double.infinity;
    for (var cluster in clusters) {
      if (cluster.length == index) {
        double d = distance(cluster[index - 1], cluster[index]);
        if (d < minDist) minDist = d;
      }
    }
    return minDist;
  }

  List<List<int>> clusters = List.generate(k, (_) => []);

  clusters[0].add(0);
  clusters[1].add(0);

  List<int> pointsInCluster(int idx) => clusters[idx];

  int findClosest(List<double> point) {
    int minIdx = 0, minDist = distance(point, points[0]);
    for (int i = 1; i < points.length; i++) {
      double d = distance(point, points[i]);
      if (d < minDist) {
        minDist = d;
        minIdx = i;
      }
    }
    return minIdx;
  }

  bool needRecluster(List<List<int>> clusters) {
    for (int i = 1; i < clusters.length; i++) {
      if (pointsInCluster(i).length != pointsInCluster(0).length) return true;
      for (int j = 0; j < pointsInCluster(i).length; j++) {
        int idx = findClosest(points[pointsInCluster(i)[j]]);
        if (idx != pointsInCluster(0)[j]) return true;
      }
    }
    return false;
  }

  print('Cluster $k:');
  print('  Points: $pointsInCluster(0)');
  print(' centroid: ${points[pointsInCluster(0)[0]]}');

  int iteration = 0;
  while (needRecluster(clusters)) {

    List<int> newClusters = List.generate(k, (_) => []);

    for (int i = 0; i < points.length; i++) {
      int idx = findClosest(points[i]);
      if (idx != pointsInCluster(0).length) {
        newClusters[idx].add(i);
      } else {
        newClusters[0].add(i);
      }
    }

    clusters = List.from(newClusters);

    print('Cluster $k:');
    print('  Points: $pointsInCluster(0)');
    print(' centroid: ${points[pointsInCluster(0)[0]]}');

    iteration++;
  }

  print('Converged in $iteration iteration(s).');
}

