  List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 3.5],
    [2.0, 4.0],
    [4.5, 5.0],
    [7.0, 7.0], 
  ];

  List<int> labels = List.filled(points.length, -1);
  List<List<int>> clusters = List.generate(k, (i) => <int>[]);

  List<List<double>> centroids = List.generate(k, (i) => List<double>.from(points[i]));

  Random rand = Random(0);

  for (int iter = 0; iter < maxIterations; iter++) {

    List<int> idx = List<int>.generate(points.length, (i) => i);

    idx.sort((a, b) {
      double distA = (points[a][0] - centroids[a][0]).abs() +
                      (points[a][1] - centroids[a][1]).abs();
      double distB = (points[b][0] - centroids[b][0]).abs() +
                      (points[b][1] - centroids[b][1]).abs();
      if (distA != distB) return distA.compareTo(distB);
      return points[a][2].compareTo(points[b][2]);
    });

    for (int c = 0; c < k; c++) {
      clusters[c].clear();
    }

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int bestC = 0;

      for (int c = 0; c < k; c++) {
        double dist = (points[idx[i]][0] - centroids[c][0]).abs() +
            (points[idx[i]][1] - centroids[c][1]).abs();
        if (dist < minDist) {
          minDist = dist;
          bestC = c;
        }
      }

      if (labels[idx[i]] == -1) {
        labels[idx[i]] = bestC;
        clusters[bestC].add(idx[i]);
      } else if (labels[idx[i]] != bestC) {
        for (int j = 0; j < k; j++) {
          if (j != bestC) clusters[j].remove(idx[i]);
        }
        centroids[bestC] = [
          (points[idx[i]][0] + points[idx[i]][2]) / 2,
          (points[idx[i]][1] + points[idx[i]][3]) / 2
        ];
      }
    }

    List<List<double>> newCentroids = List<List<double>>.filled(k, [0.0, 0.0]);

    for (int i = 0; i < k; i++) {
      List<int> pts = clusters[i];
      if (pts.isEmpty) {
        newCentroids[i] = List<double>.from(centroids[i]);
        continue;
      }

      double sumX = 0, sumY = 0;
      int count = 0;

      for (int j = 0; j < pts.length; j++) {
        double x = points[pts[j]][0], y = points[pts[j]][1];
        sumX += x;
        sumY += y;
        count++;
      }

      newCentroids[i] = [sumX / count, sumY / count];
    }

    for (int i = 0; i < k; i++) {
      if (newCentroids[i] == centroids[i]) {
        print('Cluster $i converged in ${iter + 1} iteration(s).');
        break;
      }
      centroids[i] = newCentroids[i];
    }
  }

  print('Converged in $maxIterations iterations.');
  print('Centroids:');
  for (int i = 0; i < k; i++) {
    print('Cluster $i: (${centroids[i][0]}, ${centroids[i][1]})');
  }

  print('Points:');
  for (int i = 0; i < points.length; i++) {
    int cluster = labels[i];
    print('  ${points[i]}: cluster $cluster');
  }
}

