    [5, 5],
    [5, 6],
    [6, 6],
    [6, 7],
  ];

  const int k = 2;

  const double eps = 0.01;
  const int maxIter = 100;

  final int n = data.length;

  final int d = data[0].length;

  final Set<int> visited = {};

  final List<int> clusterLabels = List<int>.filled(n, -1);

  final List<int> centroids = List<int>.generate(k, (_) => random.nextInt(d));

  int findClosest(int i) {
    double minDist = double.infinity;
    int closest = -1;
    for (int j = 0; j < k; j++) {
      double dist = 0;
      for (int d = 0; d < d; d++) {
        dist += pow(data[i][d] - centroids[j][d], 2);
      }
      if (dist < minDist) {
        minDist = dist;
        closest = j;
      }
    }
    return closest;
  }

  bool isConverged(List<int> clusterLabels) {
    for (int i = 0; i < n - 1; i++) {
      if (clusterLabels[i] != clusterLabels[i + 1]) return false;
    }
    return true;
  }

  for (int iter = 0; iter < maxIter; iter++) {

    for (int i = 0; i < n; i++) {

      int clusterIdx = findClosest(i);

      if (clusterLabels[i] == -1) {
        clusterLabels[i] = clusterIdx;
        visited.add(clusterIdx);
      } else if (clusterLabels[i] != clusterIdx) {
        for (int j = 0; j < k; j++) {
          if (visited.contains(j)) continue;
          if (j == clusterIdx) continue;
          double dist = 0;
          for (int d = 0; d < d; d++) {
            dist += pow(data[i][d] - centroids[j][d], 2);
          }
          if (dist < eps) {
            clusterLabels[i] = j;
            visited.add(j);
            break;
          }
        }
      }

      centroids[clusterIdx] = (1 - (1 / (iter + 1))) * data[i] + (1 / (iter + 1)) * centroids[clusterIdx];
    }

    if (isConverged(clusterLabels)) {
      break;
    }
  }

  print('Cluster $clusterLabels');
  print('  Points: ${List<int>.from(data)}');
  print(' centroid: ${List<double>.from(centroids)}');
  print('Converged in $iter iteration(s).');
}

