void fn0() {

  final Random rand = Random(0);

  final List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 3.0],
    [3.5, 4.0],
    [3.5, 4.5],
    [5.0, 5.0],
    [7.0, 7.0],
  ];

  const int k = 3; 
  const double eps = 1e-4; 
  const int maxIterations = 100;

  final Set<int> visited = <int>{};
  List<int> parent = List.filled(points.length, -1);

  void unionFind(int x, int y) {

    if (parent[x] == -1) {
      parent[x] = y;
    } else if (parent[y] == -1) {
      parent[y] = x;
    } else {

      int rootX = parent[x];
      int rootY = parent[y];

      parent[rootX] = rootY;
    }
  }

  double distance(List<double> p1, List<double> p2) {
    double sum = 0;
    for (int i = 0; i < p1.length; i++) {
      sum += pow(p1[i] - p2[i], 2);
    }
    return sqrt(sum);
  }

  bool isNeighbor(List<double> p1, List<double> p2) {
    double dist = distance(p1, p2);
    return dist < eps;
  }

  bool find(int x) {
    return parent[x] == x;
  }

  void cluster(int index) {
    if (points.length <= 1) return;

    final int clusterIndex = index;

    final int n = points.length;
    visited.add(clusterIndex);

    for (int i = 0; i < n; i++) {
      if (i == clusterIndex) continue;

      if (!visited.contains(i)) {

        final List<double> pi = List.from(points[i]);

        int newParent = -1;
        for (int j = 0; j < n; j++) {
          if (!visited.contains(j)) {

            final List<double> pj = List.from(points[j]);

            if (isNeighbor(pi, pj)) {
              unionFind(i, j);
              newParent = j;
              break;
            }
          }
        }

        if (newParent == -1) {

          newParent = n;
          points.add(pi);
        }

        visited.add(newParent);
        cluster(newParent);
      }
    }
  }

  for (int i = 0; i < n; i++) {
    if (find(i)) continue;

    final List<double> pi = List.from(points[i]);
    final int newParent = n;
    points.add(pi);

    visited.add(newParent);
    cluster(newParent);
  }

  print('Converged in ${maxIterations} iteration(s).');
  print('Cluster ${clusterIndex}:');
  print('  Points: ${points.sublist(clusterIndex)}');
  print(' centroid: ${points[clusterIndex]}');
}

