  int minPts = 2; 

  List<int> clusterLabels = List<int>.filled(points.length, 0);

  Set<int> visited = {};

  List<int> regionQuery(int index) {
    List<int> queue = [];
    queue.add(index);
    visited.add(index);

    while (queue.isNotEmpty) {
      int current = queue.removeAt(0);
      for (int neighborIndex = 0; neighborIndex < points.length; neighborIndex++) {
        if (points[current][0] == points[neighborIndex][0] &&
            points[current][1] == points[neighborIndex][1] &&
            !visited.contains(neighborIndex)) {
          queue.add(neighborIndex);
          visited.add(neighborIndex);
        }
      }
    }
    return clusterLabels;
  }

  for (int i = 0; i < points.length; i++) {
    clusterLabels[i] = -1;
  }

  for (int i = 0; i < points.length; i++) {
    if (clusterLabels[i] != 0) continue; 
    clusterLabels = regionQuery(i);
    if (clusterLabels[i] != -1) {
      clusterLabels[i] = k;
    }
  }

  int clusterCount = 0;
  for (int c = 0; c < clusterLabels.length; c++) {
    if (clusterLabels[c] == k) {
      clusterCount++;
    }
  }

  print('Cluster ${clusterCount}  Points: ${points.map((p) => '${p[0]},${p[1]}').toList()}');
  print('centroid: ${points[clusterLabels.indexOf(k)]}');

  int iteration = 0;
  while (iteration < maxIterations) {

    List<List<int>> clusters = [];
    for (int c = 0; c < points.length; c++) {
      if (clusterLabels[c] == k) {
        clusters.add(List<int>.from(points[c]));
      }
    }

    List<double> clusterCentroids = [];
    for (List<int> points in clusters) {
      double cx = 0, cy = 0, count = 0;
      for (int pt in points) {
        cx += pt[0];
        cy += pt[1];
        count++;
      }
      clusterCentroids.add([cx / count, cy / count]);
    }

    for (int i = 0; i < points.length; i++) {
      double minD = double.infinity;
      int bestCluster = -1;
      for (int c = 0; c < clusters.length; c++) {
        double d = points[i][0] - clusterCentroids[c][0];
        double h = points[i][1] - clusterCentroids[c][1];
        double dist = d * d + h * h;
        if (dist < minD) {
          minD = dist;
          bestCluster = c;
        }
      }
      if (minD <= eps && bestCluster != clusterLabels[i]) {
        clusterLabels[i] = k;
      }
    }

    int changed = 0;
    for (int c = 0; c < clusterLabels.length; c++) {
      if (clusterLabels[c] != k) {
        changed++;
      }
    }
    if (changed == 0) {
      print('Converged in $iteration iteration(s).');
      break;
    }
    iteration++;
  }

  for (int c = 0; c < clusterLabels.length; c++) {
    if (clusterLabels[c] == k) {
      print('Cluster $k  Points: ${points.map((p) => '${p[0]},${p[1]}').toList()}');
    }
  }
}

